import { BrowserRouter, Routes, Route } from 'react-router-dom';

// Providers
import { AuthProvider } from './context/AuthContext';
import { SearchProvider } from './context/SearchContext'; 
import { CartProvider } from './context/CartContext';     

// Layouts & Guards
import { ProtectedRoute } from './features/auth/ProtectedRoute';
import { DashboardLayout } from './layouts/DashboardLayout';
import { CartDrawer } from './features/orders/CartDrawer'; 

// Pages
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Marketplace } from './pages/Marketplace';
import { Orders } from './pages/Orders';
import { Reports } from './pages/Reports';

// NEW Pages imported here:
import { SavedItems } from './pages/SavedItems';
import { Messages } from './pages/Messages';
import { TransportLogistics } from './pages/TransportLogistics';
import { PriceTrends } from './pages/PriceTrends';
import { FarmersPartners } from './pages/FarmersPartners';
import { Settings } from './pages/Settings';

export default function App() {
  return (
    <AuthProvider>
      <CartProvider>
        <SearchProvider>
          <BrowserRouter>
            <Routes>
              {/* Public Routes */}
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />

              {/* Protected Routes mapped to the Sidebar */}
              <Route path="/" element={<ProtectedRoute><DashboardLayout><Marketplace /></DashboardLayout></ProtectedRoute>} />
              <Route path="/marketplace" element={<ProtectedRoute><DashboardLayout><Marketplace /></DashboardLayout></ProtectedRoute>} />
              <Route path="/orders" element={<ProtectedRoute><DashboardLayout><Orders /></DashboardLayout></ProtectedRoute>} />
              <Route path="/reports" element={<ProtectedRoute allowedRoles={['admin']}><DashboardLayout><Reports /></DashboardLayout></ProtectedRoute>} />

              {/* NEW Sidebar Routes */}
              <Route path="/saved" element={<ProtectedRoute><DashboardLayout><SavedItems /></DashboardLayout></ProtectedRoute>} />
              <Route path="/messages" element={<ProtectedRoute><DashboardLayout><Messages /></DashboardLayout></ProtectedRoute>} />
              <Route path="/transport" element={<ProtectedRoute><DashboardLayout><TransportLogistics /></DashboardLayout></ProtectedRoute>} />
              <Route path="/trends" element={<ProtectedRoute><DashboardLayout><PriceTrends /></DashboardLayout></ProtectedRoute>} />
              <Route path="/farmers" element={<ProtectedRoute><DashboardLayout><FarmersPartners /></DashboardLayout></ProtectedRoute>} />
              <Route path="/settings" element={<ProtectedRoute><DashboardLayout><Settings /></DashboardLayout></ProtectedRoute>} />

            </Routes>
            <CartDrawer />
          </BrowserRouter>
        </SearchProvider>
      </CartProvider>
    </AuthProvider>
  );
}
